do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$ABB$q$,$q$public_company$q$),($q$BASX$q$,$q$private_company$q$),($q$Babcock & Wilcox Enterprises$q$,$q$public_company$q$),($q$Base Electron$q$,$q$private_company$q$),($q$Bitdeer Technologies Group$q$,$q$public_company$q$),($q$Caterpillar$q$,$q$public_company$q$),($q$ChronoScale$q$,$q$public_company$q$),($q$Cipher Digital$q$,$q$public_company$q$),($q$CleanSpark$q$,$q$public_company$q$),($q$Core Scientific$q$,$q$public_company$q$),($q$Corintis$q$,$q$private_company$q$),($q$Digital Realty Trust$q$,$q$public_company$q$),($q$Equinix$q$,$q$public_company$q$),($q$Fermi$q$,$q$public_company$q$),($q$Galaxy Digital$q$,$q$public_company$q$),($q$HIVE Digital Technologies$q$,$q$public_company$q$),($q$Hut 8$q$,$q$public_company$q$),($q$IREN$q$,$q$public_company$q$),($q$Keel Infrastructure$q$,$q$public_company$q$),($q$MARA Holdings$q$,$q$public_company$q$),($q$Riot Platforms$q$,$q$public_company$q$),($q$TeraWulf$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Because power distribution, cooling architecture, and data hall layouts are standardized across our campuses, we are able to consolidate purchasing around a common set of trusted, qualified partners—including ABB for electrical equipment, BASX for mechanical and cooling systems, and Caterpillar for backup generation—and to place bulk orders against a multi-gigawatt development pipeline.$q$),(2,$q$Gain on change in fair value of investment was $10.8 million for the fiscal year ended May 31, 2026, due to an increase of $8.8 million in fair value of our investment in BWE common stock and an increase of $2.0 million in fair value of our investment in Base Electron, a related party.$q$),(3,$q$Immediately following the closing of the Cloud Business Combination, the Company (on an aggregate basis with Contributor), owned approximately 97% of the issued and outstanding equity of ChronoScale.$q$),(4,$q$In addition, through our partnership with Base Electron Corporation ("Base Electron"), an independent power producer, we are pursuing the development of approximately 1.2 GW of front-of-the-meter, natural gas-fired generation in the Dakotas, which we expect to unlock additional power capacity for our development pipeline.$q$),(5,$q$In connection with and as partial consideration for the Company’s entry into the Guarantee, Base Electron issued to the Company approximately $q$),(6,$q$On May 28, 2025, APLD ELN-02 LLC and APLD ELN-03 LLC, our subsidiaries, each entered into a data center lease (the “ELN-02 Lease” and the “ELN-03 Lease”) with CoreWeave, Inc. (“CoreWeave”) to deliver an aggregate of 250 MW of infrastructure to host CoreWeave’s HPC operations at Polaris Forge 1.$q$),(7,$q$On May 28, 2025, in connection with the entry into the data center leases with CoreWeave for Building 2 and Building 3 (the "CoreWeave Leases"), the Company issued to CoreWeave a warrant (the “CoreWeave Warrant”) to acquire up to $q$),(8,$q$On May 28, 2025, our subsidiaries APLD ELN-02 LLC and APLD ELN-03 LLC each entered into a data center lease (the "ELN-02 Lease" and the "ELN-03 Lease”) with CoreWeave, Inc. (“CoreWeave”) to deliver an aggregate of 250 MW of capacity to host CoreWeave’s HPC operations at Polaris Forge 1.$q$),(9,$q$The balance also includes an investment by the Company in Corintis SA ("Corintis") in exchange for Series A1 preferred shares.$q$),(10,$q$The investment in Base Electron will be accounted for at cost under ASC 321 as it is an equity security without a readily determinable fair value and will be evaluated quarterly for impairment indicators.$q$),(11,$q$We compete with established data center owners and operators, including Digital Realty Trust, Inc. and Equinix, Inc., as well as hyperscalers that develop their own capacity, independent and private data center developers, and other power-advantaged developers, including companies that have expanded from blockchain hosting into HPC infrastructure, such as IREN Limited, Cipher Digital Inc., TeraWulf Inc., Hut 8 Corp., Riot Platforms, Inc., CleanSpark, Inc., HIVE Digital Technologies Ltd., Core Scientific, Inc., Bitdeer Technologies Group, Galaxy Digital Inc., Fermi Inc., Keel Infrastructure Corp, and MARA Holdings, Inc.$q$),(12,$q$We recently completed the separation of our cloud business segment into a separate publicly traded company, ChronoScale, of which we currently own approximately 96%.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$sells_to$q$,$q$APLD$q$,$q$CoreWeave$q$,$q${8,6,7}$q$::int[],$q${business,mdna,mdna}$q$::text[],null,null,null,null),(2,$q$partners$q$,$q$APLD$q$,$q$Base Electron$q$,$q${4}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(3,$q$invests$q$,$q$APLD$q$,$q$ChronoScale$q$,$q${12,3}$q$::int[],$q${risk_factors,mdna}$q$::text[],96,$q$approximate$q$,$q$source_revenue$q$,null),(4,$q$supplies$q$,$q$ABB$q$,$q$APLD$q$,$q${1}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(5,$q$supplies$q$,$q$BASX$q$,$q$APLD$q$,$q${1}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(6,$q$supplies$q$,$q$Caterpillar$q$,$q$APLD$q$,$q${1}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(7,$q$competes$q$,$q$APLD$q$,$q$Digital Realty Trust$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(8,$q$competes$q$,$q$APLD$q$,$q$Equinix$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(9,$q$competes$q$,$q$APLD$q$,$q$IREN$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(10,$q$competes$q$,$q$APLD$q$,$q$Cipher Digital$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(11,$q$competes$q$,$q$APLD$q$,$q$TeraWulf$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(12,$q$competes$q$,$q$APLD$q$,$q$Hut 8$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(13,$q$competes$q$,$q$APLD$q$,$q$Riot Platforms$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(14,$q$competes$q$,$q$APLD$q$,$q$CleanSpark$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(15,$q$competes$q$,$q$APLD$q$,$q$HIVE Digital Technologies$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(16,$q$competes$q$,$q$APLD$q$,$q$Core Scientific$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(17,$q$competes$q$,$q$APLD$q$,$q$Bitdeer Technologies Group$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(18,$q$competes$q$,$q$APLD$q$,$q$Galaxy Digital$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(19,$q$competes$q$,$q$APLD$q$,$q$Fermi$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(20,$q$competes$q$,$q$APLD$q$,$q$Keel Infrastructure$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(21,$q$competes$q$,$q$APLD$q$,$q$MARA Holdings$q$,$q${11}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(22,$q$invests$q$,$q$APLD$q$,$q$Babcock & Wilcox Enterprises$q$,$q${2}$q$::int[],$q${mdna}$q$::text[],null,null,null,null),(23,$q$invests$q$,$q$APLD$q$,$q$Base Electron$q$,$q${2,5,10}$q$::int[],$q${mdna,notes,notes}$q$::text[],null,null,null,null),(24,$q$invests$q$,$q$APLD$q$,$q$Corintis$q$,$q${9}$q$::int[],$q${notes}$q$::text[],4,$q$approximate$q$,$q$source_revenue$q$,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$CoreWeave$q$ then ticker=$q$CRWV$q$ when $q$APLD$q$ then ticker=$q$APLD$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$APLD M6 group 2-4$q$,'claude-sonnet-5-5',301030,11561,0.9967,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1144879/000114487926000048/apld-20260531.htm$q$,r.sec[k],t,true,$q$2026-07-29$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
